/**
 * Generates typed `as const` ABIs from the Foundry build output so viem/wagmi infer every call.
 * Run after `forge build`. The generated files are committed so the web/api build without Foundry.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const out = join(here, "../../contracts/out");
const dest = join(here, "../src/abi");

const contracts: Array<[file: string, name: string, exportName: string]> = [
  ["BettingMarket.sol", "BettingMarket", "bettingMarketAbi"],
  ["MockUSDC.sol", "MockUSDC", "mockUsdcAbi"],
  ["MockOracleAdapter.sol", "MockOracleAdapter", "oracleAdapterAbi"],
];

let index = "// Generated by scripts/gen-abi.ts — do not edit.\n";
for (const [file, name, exportName] of contracts) {
  const artifact = JSON.parse(readFileSync(join(out, file, `${name}.json`), "utf8"));
  const body = `// Generated by scripts/gen-abi.ts from packages/contracts/out/${file} — do not edit.\nexport const ${exportName} = ${JSON.stringify(artifact.abi, null, 2)} as const;\n`;
  writeFileSync(join(dest, `${name}.ts`), body);
  index += `export { ${exportName} } from "./${name}";\n`;
  console.log(`wrote ${name}.ts (${artifact.abi.length} entries)`);
}
writeFileSync(join(dest, "index.ts"), index);
